import { Helmet } from "react-helmet-async";
import { Typography } from "@mui/material";
import Footer from "../Footer";
import "./infoPages.css";
import "./Etichette.css";

const Etichette = () => {

  const items = [
    {
      title: "Nome etichetta 1",
      description: "Lorem Ipsum is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry's standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book. It has survived not only five centuries, but also the leap into electronic typesetting, remaining essentially unchanged. It was popularised in the 1960s with the release of Letraset sheets containing Lorem Ipsum passages, and more recently with desktop publishing software like Aldus PageMaker including versions of Lorem Ipsum.",
      img: "/label_1.png",
    },
    {
      title: "Nome etichetta 2",
      description: "Lorem Ipsum is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry's standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book. It has survived not only five centuries, but also the leap into electronic typesetting, remaining essentially unchanged. It was popularised in the 1960s with the release of Letraset sheets containing Lorem Ipsum passages, and more recently with desktop publishing software like Aldus PageMaker including versions of Lorem Ipsum.",
      img: "/label_2.png",
    },
    {
      title: "Nome etichetta 3",
      description: "Lorem Ipsum is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry's standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book. It has survived not only five centuries, but also the leap into electronic typesetting, remaining essentially unchanged. It was popularised in the 1960s with the release of Letraset sheets containing Lorem Ipsum passages, and more recently with desktop publishing software like Aldus PageMaker including versions of Lorem Ipsum.",
      img: "/label_3.png",
    },
  ];


  return (
    <div className="etichette-page">
      <Helmet>
        <title>Le Nostre Etichette – Olio Ruocco</title>
        <meta name="description" content="Scopri le etichette di Olio Ruocco: ogni linea racconta la storia e le caratteristiche del nostro olio extravergine di oliva Biologico - BIO." />
      </Helmet>
      <div className="infoPageContainer">
        <div className="etichette-container">

          {items.map((it, idx) => {
            const reverse = idx % 2 === 1;
            return (
              <section
                key={idx}
                className="etichette-bleed"
                style={{ backgroundImage: `linear-gradient(rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.2)), url(${it.img})` }}
              >
                <div className={`etichette-card ${reverse ? "reverse" : ""}`}>
                  <img
                    className="etichette-image"
                    src={it.img}
                    alt={it.title}
                  />

                  <div className="etichette-text">
                    <div className="categoryTitleContainerCustom">
                      <h2 className="categoryTitle">{it.title}</h2>
                      <div className="separator" />
                    </div>
                    <Typography style={{ marginTop: 12 }}>{it.description}</Typography>
                  </div>
                </div>
              </section>
            );
          })}
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default Etichette;
