import { Helmet } from "react-helmet-async";
import HomeHeader from "./HomeHeader";
import CatalogHome from "./CatalogHome";
import MidHome from "./MidHome";
import FAQComponent from "./FAQComponent";
import BlogHome from "./BlogHome";

import "./Home.css";
import Footer from "../Footer";
const HomePage = () => {
  return (
    <div className="homeContainer">
      <Helmet>
        <title>Olio Ruocco - Olio Evo, Biologico, Irpino</title>
        {/* Meta Description */}
        <meta
          name="description"
          content="Olio Ruocco produce olio extravergine di oliva biologico in Irpinia, a Montemarano (Avellino). Olio Ravece, Leccino e multicultivar estratti a freddo."
        />

        {/* Keywords */}
        <meta
          name="keywords"
          content="olio extravergine di oliva biologico, olio ravece irpinia, olio montemarano, olio avellino, olio campania, olio evo biologico"
        />

        {/* Canonical */}
        <link rel="canonical" href="https://www.olioruocco.github.io/" />

        {/* Open Graph (social) */}
        <meta
          property="og:title"
          content="Olio Ruocco – Olio Extravergine di Oliva Biologico Irpinia"
        />
        <meta
          property="og:description"
          content="Produzione di olio extravergine di oliva biologico a Montemarano, Avellino. Olio Ravece, Leccino e multicultivar estratti a freddo."
        />
        <meta property="og:type" content="website" />
        <meta property="og:url" content="https://www.olioruocco.github.io/" />
        <meta property="og:locale" content="it_IT" />
      </Helmet>
      {<HomeHeader></HomeHeader>}
      <CatalogHome></CatalogHome>
      <MidHome></MidHome>
      <FAQComponent />
      <BlogHome />
      <Footer />
    </div>
  );
};

export default HomePage;
