import React, { useState, useEffect } from "react";
import ImageZoom from "react-image-zooom";
import { useMediaQuery } from "@mui/material";

import "./Shop.css";

import { useSelector } from "react-redux";
import { Carousel } from "react-responsive-carousel";
import Footer from "../Footer";

import "react-responsive-carousel/lib/styles/carousel.min.css";

const styles = {
  separator_styling: { marginTop: "1rem" },
  p_container_styling: {
    display: "flex",
    flexDirection: "row",
    alignItems: "baseline",
    lineHeight: "4rem",
  },
  price_styling: { fontSize: "1.5rem", lineHeight: "2rem" },
  key_styling: { fontWeight: 600, fontSize: "large" },
  text_styling: { fontSize: "large", margin: "0rem 0.5rem" },
  thumb_img_styling: {
    maxWidth: "12vw",
    maxHeight: "12vw",
    marginLeft: "1rem",
    borderRadius: "0.5rem",
  },
  thumb_img_container_styling: { margin: "2rem 0rem", dispay: "flex" },
};

const ProductPage = () => {
  const { currentSelected } = useSelector((state) => state.products);
  const isMobileOrTablet = useMediaQuery("(max-width: 1024px)");
  const [currentPrice, setCurrentPrice] = useState(0);
  const [selectedFormatIdx, setSelectedFormatIdx] = useState(null);

  useEffect(() => {
    if (
      currentSelected &&
      currentSelected.formats &&
      currentSelected.formats.length > 0
    ) {
      const defaultIdx = currentSelected.formats.length - 1;
      setSelectedFormatIdx(defaultIdx);
      setCurrentPrice(currentSelected.formats[defaultIdx].price);
    } else {
      setSelectedFormatIdx(null);
      setCurrentPrice(0);
    }
  }, [currentSelected]);

  let imagePaths = [
    currentSelected.bgImage,
    `/${currentSelected.type}/label_${currentSelected.title} - ${currentSelected.size}.png`,
    `/${currentSelected.type}/label_${currentSelected.title} - ${currentSelected.size}_b.png`,
  ];

  // responsive styles
  const responsiveKeyStyling = isMobileOrTablet
    ? { ...styles.key_styling, fontSize: "1rem", lineHeight: "1.4rem" }
    : styles.key_styling;

  const responsiveTextStyling = isMobileOrTablet
    ? { ...styles.text_styling, fontSize: "0.95rem", margin: "0.25rem 0.5rem" }
    : styles.text_styling;

  const responsivePContainer = isMobileOrTablet
    ? {
        ...styles.p_container_styling,
        lineHeight: "1.6rem",
        alignItems: "center",
      }
    : styles.p_container_styling;

  const renderSliderContent = () => {
    let images = [];
    for (let [i, imgPath] of imagePaths.entries()) {
      images.push(
        <div key={i}>
          {isMobileOrTablet ? (
            <img
              className={"productPageMainImg"}
              src={imgPath}
              alt="product page main"
              style={{ width: "100%", display: "block" }}
            />
          ) : (
            <ImageZoom
              className={"productPageMainImg"}
              src={imgPath}
              alt="product page main"
              zoom="200"
            />
          )}
        </div>,
      );
    }
    return images;
  };

  const renderCustomThumbs = (children) => {
    return children.map((child, i) => (
      <img key={i} src={child.props.children.props.src} alt="" />
    ));
  };


  const renderCurrentPrice = () => {
    if(currentPrice){
      return `€${currentPrice} - €${parseFloat(currentPrice)/parseFloat(currentSelected.formats[selectedFormatIdx].size)} al L.`;  
    }
    return `€${currentSelected.price}`;
  };

  return (
    <div className="productPage">
      <div className="productPageContainer">
        <div className="productPageSlider">
          <Carousel
            showArrows={false}
            showStatus={false}
            showIndicators={true}
            showThumbs={true}
            autoPlay={false}
            transitionTime={500}
            renderThumbs={renderCustomThumbs}
            className={"productPageMainImg"}
            thumbWidth={150}
          >
            {renderSliderContent()}
          </Carousel>
        </div>

        <div className={"productPageContentContainer"}>
          <div className={"productPageTitle"}>
            {`${currentSelected.title} ${currentSelected.type}`}
          </div>
          <div style={styles.separator_styling} className={"separator"} />
          <p
            style={styles.price_styling}
          >{renderCurrentPrice()}</p>
          <div style={responsivePContainer}>
            <p style={responsiveKeyStyling}>Dimensioni:</p>
            {currentSelected.formats && currentSelected.formats.length > 0 ? (
              <div
                style={{
                  display: "flex",
                  gap: "0.6rem",
                  alignItems: "center",
                  flexWrap: "wrap",
                  margin: "0 1rem",
                }}
              >
                {currentSelected.formats.map((f, i) => {
                  const isSelected = selectedFormatIdx === i;
                  return (
                    <button
                      key={i}
                      type="button"
                      onClick={() => {
                        setSelectedFormatIdx(i);
                        setCurrentPrice(f.price);
                      }}
                      style={{
                        padding: "0.45rem 0.8rem",
                        borderRadius: "0.5rem",
                        border: isSelected
                          ? "1px solid #333"
                          : "1px solid #d0d0d0",
                        background: isSelected ? "#333" : "#fff",
                        color: isSelected ? "#fff" : "#000",
                        cursor: "pointer",
                        fontWeight: 700,
                      }}
                    >
                      {f.size}l
                    </button>
                  );
                })}
              </div>
            ) : (
              <p style={responsiveTextStyling}>{currentSelected.size}</p>
            )}
          </div>

          <div style={responsivePContainer}>
            <p style={responsiveKeyStyling}>Intensità:</p>
            <p style={responsiveTextStyling}>{currentSelected.intensity}</p>
          </div>

          <p style={responsiveKeyStyling}>Descrizione:</p>
          <p style={responsiveTextStyling}>{currentSelected.description}</p>

          <div style={responsivePContainer}>
            <p style={responsiveKeyStyling}>Uso in Cucina:</p>
            <p style={responsiveTextStyling}>{currentSelected.usage}</p>
          </div>

          <p style={responsiveKeyStyling}>Abbinamenti:</p>
          <p style={responsiveTextStyling}>{currentSelected.pairings}</p>

          <p style={responsiveKeyStyling}>Molitura:</p>
          <p style={responsiveTextStyling}>{currentSelected.molitura}</p>

          <p style={responsiveKeyStyling}>Sistema di Raccolta:</p>
          <p style={responsiveTextStyling}>{currentSelected.harvestSystem}</p>
        </div>
      </div>
      <p
        style={{
          display: "flex",
          justifyContent: "flex-start",
          color: "#e16162",
          fontSize: isMobileOrTablet ? "1rem" : "1.25rem",
          fontWeight: 500,
          padding: isMobileOrTablet ? "1.25rem 0.1rem" : "0 5rem",
          textAlign: "center",
        }}
      >
        Per formati personalizzati contattaci direttamente in privato.
      </p>
      <Footer />
    </div>
  );
};

export default ProductPage;
