import React from "react";
import { useNavigate } from "react-router-dom";
import { useDispatch } from "react-redux";
import { navigateTo } from "../../utils";
import { CATEGORIES } from "../../constants";
import { setFilters } from "../../Reducers/filters";

import "./ShopCategorySection.css";
import { useMediaQuery } from "@mui/material";

const ShopCategoryCards = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const isMobile = useMediaQuery("(max-width: 768px)");

  const goToShop = (categoryIndex) => {
    dispatch(setFilters({ types: [CATEGORIES[categoryIndex]] }));
    navigateTo(navigate, "/Shop");
  };

  return (
    <section className="shop-cat-section">
      {/* Header */}
      <div className="shop-cat-header">
        <h2 className="shop-cat-title">Esplora per categoria</h2>
        <button className="shop-cat-link" onClick={() => navigateTo(navigate, "/Shop")}>
          Visita Store
        </button>
      </div>

      {/* Grid: large card left, two stacked cards right */}
      <div className="shop-cat-grid">

        {/* Large card – Ravece */}
        <div
          className="shop-cat-card shop-cat-card--large"
          style={{ backgroundImage: `url("${isMobile ? "/full_bottle_xs.png" : "/full_bottle.png"}")` }}
        >
          <div className="shop-cat-card__content">
            <p className="shop-cat-card__label">Monocultivar &ldquo;Ravece&rdquo;</p>
            <button className="shop-cat-card__btn" onClick={() => goToShop(0)}>
              Scopri di più
            </button>
          </div>
        </div>

        {/* Small card – Leccino */}
        <div
          className="shop-cat-card"
          style={{ backgroundImage: 'url("/full_bottle01.png")' }}
        >
          <div className="shop-cat-card__content">
            <p className="shop-cat-card__label">Monocultivar &ldquo;Leccino&rdquo;</p>
            <button className="shop-cat-card__btn" onClick={() => goToShop(1)}>
              Scopri di più
            </button>
          </div>
        </div>

        {/* Small card – Misto */}
        <div
          className="shop-cat-card"
          style={{ backgroundImage: 'url("/full_bottle02.png")' }}
        >
          <div className="shop-cat-card__content">
            <p className="shop-cat-card__label">Multicultivar</p>
            <button className="shop-cat-card__btn" onClick={() => goToShop(2)}>
              Scopri di più
            </button>
          </div>
        </div>

      </div>
    </section>
  );
};

export default ShopCategoryCards;
