import React from "react";
import "./FAQSection.css";

const FAQS_ARRAY = [
  {
    id: 1,
    name: "Object 1",
    description: "This is the first object.",
  },
  {
    id: 2,
    name: "Object 2",
    description: "This is the second object.",
  },
  {
    id: 3,
    name: "Object 3",
    description: "This is the third object.",
  },
  {
    id: 4,
    name: "Object 4",
    description: "This is the fourth object.",
  },
  {
    id: 5,
    name: "Object 5",
    description: "This is the fifth object.",
  },
];

const FAQComponent = () => {
  const [expanded, setExpanded] = React.useState(null);

  const toggle = (id) => setExpanded((prev) => (prev === id ? null : id));

  return (
    <section className="faq-section">
      <h2 className="faq-title">F.A.Q. - Info &amp; Risposte Utili</h2>

      <div className="faq-list">
        {FAQS_ARRAY.map((faq) => {
          const isOpen = expanded === faq.id;
          return (
            <div
              key={faq.id}
              className={`faq-item${isOpen ? " faq-item--open" : ""}`}
            >
              <button
                className="faq-item__trigger"
                onClick={() => toggle(faq.id)}
                aria-expanded={isOpen}
                aria-controls={`faq-body-${faq.id}`}
                id={`faq-trigger-${faq.id}`}
              >
                <p className="faq-item__question">{faq.name}</p>
                <span className="faq-item__icon" aria-hidden="true" />
              </button>

              <div
                className="faq-item__body"
                id={`faq-body-${faq.id}`}
                role="region"
                aria-labelledby={`faq-trigger-${faq.id}`}
              >
                <p className="faq-item__answer">{faq.description}</p>
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
};

export default FAQComponent;
