import * as React from "react";
import { useNavigate } from "react-router-dom";
import AppBar from "@mui/material/AppBar";
import Box from "@mui/material/Box";
import Toolbar from "@mui/material/Toolbar";
import IconButton from "@mui/material/IconButton";
import Typography from "@mui/material/Typography";
import Menu from "@mui/material/Menu";
import MenuIcon from "@mui/icons-material/Menu";
import Container from "@mui/material/Container";
import Button from "@mui/material/Button";
import MenuItem from "@mui/material/MenuItem";
import { Outlet } from "react-router-dom";
import { navigateTo } from "../../utils";
import { useLocation } from "react-router-dom";
import { useEffect } from "react";
import "./NavBar.css";

const pages = [
  { id: "Shop", label: "Prodotti" },
  { id: "AboutUs", label: "Chi Siamo" },
  { id: "Blog", label: "Blog" },
  { id: "Contatti", label: "Contatti" },
];

function NavBar() {
  const navigate = useNavigate();
  const location = useLocation();
  const [anchorElNav, setAnchorElNav] = React.useState(null);
  const [anchorElUser, setAnchorElUser] = React.useState(null);
  const [isHomeStyle, setIsHomeStyle] = React.useState(window.scrollY < 10);

  const handleOnScroll = () => {
    if (window.scrollY > 10 && isHomeStyle) {
      setIsHomeStyle(false);
    } else {
      setIsHomeStyle(true);
    }
  };

  useEffect(() => {
    window.addEventListener("scroll", handleOnScroll);
    return () => {
      window.removeEventListener("scroll", handleOnScroll);
    };
  }, []);

  useEffect(() => {
    window.scrollTo(0, 0);
    setIsHomeStyle(window.scrollY < 10);
  }, [location]);

  const handleOpenNavMenu = (event) => {
    setAnchorElNav(event.currentTarget);
  };
  const handleOpenUserMenu = (event) => {
    setAnchorElUser(event.currentTarget);
  };

  const handleCloseNavMenu = () => {
    setAnchorElNav(null);
  };

  const handleOnClickPage = (e) => {
    navigateTo(navigate, "/" + e.target.id);
  };

  const handleCloseUserMenu = () => {
    setAnchorElUser(null);
  };

  const getAppBarStyle = () => {
    let style = { backgroundColor: "rgba(83,99,104,0.5)" };
    /*if (isHomeStyle && location.pathname === "/") {
      style = { ...style, backgroundColor: "rgba(0, 0, 0, 0.6)" };
    }*/
    return style;
  };

  return (
    <>
      <AppBar position="fixed" style={getAppBarStyle()} className="nav-bar">
        <Container>
          <Toolbar disableGutters>
            <Box
              sx={{ display: { xs: "flex", md: "none" }, justifyContent: "flex-start" }}
            >
              <img
                className="nav-logo"
                src="/logo.png"
                alt="Olio Ruocco Logo"
                onClick={() => navigateTo(navigate, "/")}
                style={{ cursor: "pointer" }}
              />
            </Box>
            <div className="nav-content">
              <Box sx={{ display: { xs: "none", md: "flex" } }}>
                <img
                  className="nav-logo"
                  src={`/logo.png`}
                  alt="fire icon"
                  onClick={() => navigateTo(navigate, "/")}
                />
              </Box>

              <Box
                justifyContent={"center"}
                sx={{ flexGrow: 1, display: { xs: "none", md: "flex" } }}
              >
                {pages.map((page) => (
                  <Button
                    id={page.id}
                    key={page.id}
                    onClick={handleOnClickPage}
                    sx={{ my: 2, color: "white", display: "block" }}
                  >
                    {page.label}
                  </Button>
                ))}
              </Box>
            </div>
            <Box sx={{ display: { xs: "flex", md: "none" }, ml: "auto" }}>
              <IconButton
                size="large"
                aria-label="account of current user"
                aria-controls="menu-appbar"
                aria-haspopup="true"
                onClick={handleOpenNavMenu}
                color="inherit"
              >
                <MenuIcon />
              </IconButton>
              <Menu
                id="menu-appbar"
                anchorEl={anchorElNav}
                anchorOrigin={{
                  vertical: "bottom",
                  horizontal: "right",
                }}
                keepMounted
                transformOrigin={{
                  vertical: "top",
                  horizontal: "right",
                }}
                open={Boolean(anchorElNav)}
                onClose={handleCloseNavMenu}
                sx={{ display: { xs: "block", md: "none" } }}
              >
                <MenuItem key="home" onClick={() => { handleCloseNavMenu(); navigateTo(navigate, "/"); }}>
                  <Typography sx={{ textAlign: "center" }}>Home</Typography>
                </MenuItem>
                {pages.map((page) => (
                  <MenuItem key={page.id} onClick={() => { handleCloseNavMenu(); navigateTo(navigate, "/" + page.id); }}>
                    <Typography sx={{ textAlign: "center" }}>
                      {page.label}
                    </Typography>
                  </MenuItem>
                ))}
              </Menu>
            </Box>
          </Toolbar>
        </Container>
      </AppBar>
      <Outlet />
    </>
  );
}
export default NavBar;
