import { useEffect, useRef } from "react";

export default function TreeGen() {
  const sketchRef = useRef(null);
  const p5Instance = useRef(null);

  useEffect(() => {
    if (!window.p5) {
      console.error("p5 is not loaded from CDN.");
      return;
    }

    class Branch {
      constructor(drawStart, angle, lineWeight, length, recurseLevel) {
        this.branches = [];
        this.progress = 0;
        this.drawStart = drawStart;
        this.angle = angle;
        this.lineWeight = lineWeight;
        this.lengthToDraw = length;
        this.recurseLevel = recurseLevel;
      }

      draw(p) {
        if (this.progress < 1) {
          let drawEndX = this.drawStart.x;
          let drawEndY = this.drawStart.y;

          let curveOffset =
            Math.sin(this.progress * Math.PI) *
            p.random(-0.3, 0.3) *
            (1 + this.recurseLevel * 0.2);
          let angleWithCurve = this.angle + curveOffset;

          drawEndX += p.cos(angleWithCurve) * (this.lengthToDraw * 0.1);
          drawEndY += p.sin(angleWithCurve) * (this.lengthToDraw * 0.1);

          p.stroke(50);

          if (this.recurseLevel >= 3) {
            //p.stroke(80, 90, 80, 180); // leaf color
            p.strokeWeight(p.random(2, 4)); // thicker leaves
          } else {
            if (this.recurseLevel === 0 && this.progress === 0) {
              const baseWidth = this.lineWeight*2 ; // Wider flat bottom
              p.stroke(50); // dark gray
              p.strokeWeight(this.lineWeight/2);
              p.line(
                this.drawStart.x - baseWidth / 2,
                this.drawStart.y,
                this.drawStart.x + baseWidth / 2,
                this.drawStart.y
              );
            } else {
              const taper = p.map(this.progress, 0, 1, 2.5, 1);

              //p.stroke(100 + this.recurseLevel * 10, 95, 85); // trunk color
              p.strokeWeight(this.lineWeight * taper);
            }
          }

          p.line(this.drawStart.x, this.drawStart.y, drawEndX, drawEndY);

          this.drawStart.set(drawEndX, drawEndY);
          this.progress += 0.1;

          if (p.random() > 0.7 && this.progress > 0.6) {
            this.spawnBranch(p);
          }

          if (this.progress >= 1) {
            this.spawnBranches(p);
          }
        } else {
          for (const branch of this.branches) {
            branch.draw(p);
          }
        }
      }

      spawnBranch(p) {
        if (this.recurseLevel >= 6) return;

        const angleVariance = p.PI * 0.3;
        const newAngle = this.angle + p.random(-angleVariance, angleVariance);
        const newWeight = this.lineWeight * p.random(0.4, 0.6);
        const newLength = this.lengthToDraw * p.random(0.5, 0.7);
        const recurseLevel = this.recurseLevel + 1;

        const newBranch = new Branch(
          this.drawStart.copy(),
          newAngle,
          newWeight,
          newLength,
          recurseLevel
        );
        this.branches.push(newBranch);
      }

      spawnBranches(p) {
        const nBranches =
          this.recurseLevel >= 3
            ? Math.floor(p.random(0, 2)) // more leaves
            : Math.floor(p.random(2, 5)); // denser structure
        for (let i = 0; i < nBranches; i++) {
          this.spawnBranch(p);
        }
      }
    }

    class Game {
      constructor(p) {
        this.p = p;
        this.trees = [];
        this.drawNewTrees();
      }

      drawNewTrees() {
        const p = this.p;
        //p.background(235, 235, 230);

        const numTrees = Math.floor(p.random(10, 13));
        this.trees = [];

        const spacing = p.width / (numTrees + 1);
        for (let i = 0; i < numTrees; i++) {
          const x = spacing * (i + 1);
          const y = p.height * 0.98;

          const initialDrawStart = p.createVector(x, y);
          const initialAngle = p.PI * -0.5;
          const initialLength = p.random(90, 160); // random tree height
          const initialWeight = p.map(initialLength, 140, 240, 16, 28); // scale trunk weight to match height
          const initialRecurseLevel = 0;

          const tree = new Branch(
            initialDrawStart,
            initialAngle,
            initialWeight,
            initialLength,
            initialRecurseLevel
          );
          this.trees.push(tree);
        }
      }

      draw() {
        for (const tree of this.trees) {
          tree.draw(this.p);
        }
      }
    }

    const sketch = (p) => {
      let game;
      let bgImg;

      p.preload = () => {
        bgImg = p.loadImage("/homeHeader.png"); // path from public folder
      };

      p.setup = () => {
        p.createCanvas(window.innerWidth, window.innerHeight).parent(
          sketchRef.current
        );

        // draw the background image once
        p.image(bgImg, 0, 0, p.width, p.height);

        game = new Game(p);
      };

      p.draw = () => {
        // redraw background image every frame
        //p.image(bgImg, 0, 0, p.width, p.height);

        game.draw();
      };

      p.windowResized = () => {
        p.resizeCanvas(window.innerWidth, window.innerHeight);
        p.image(bgImg, 0, 0, p.width, p.height);
        game.drawNewTrees();
      };
    };

    p5Instance.current = new window.p5(sketch);

    return () => {
      p5Instance.current.remove();
    };
  }, []);

  return (
    <div>
      <div ref={sketchRef}></div>
    </div>
  );
}
