import React from "react";
import ProductCard from "../shop/ProductsCard";
import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import { navigateTo } from "../../utils";
import { SIZES_LABEL } from "../../constants";

import "./HotProductsSection.css";

const CatalogHome = () => {
  const { products } = useSelector((state) => state.products);
  const navigate = useNavigate();

  const renderHotProducts = () =>
    products.flatMap((productType) =>
      productType
        .filter((p) => p.isHot)
        .map((product, i) => (
          <ProductCard
            key={`hot_${i}`}
            isAvailable={product.isAvailable}
            enableDisplay={false}
            stocksNum={product.stoks}
            isHome={true}
            type={product.type}
            title={product.name}
            price={product.price}
            bgImage={product.image}
            size={SIZES_LABEL[product.size]}
            description={product.description || ""}
            usage={product.usage || ""}
            pairings={product.pairings || ""}
            intensity={product.intensity || ""}
            molitura={product.molitura || ""}
            harvestSystem={product.harvestSystem || ""}
          />
        ))
    );

  return (
    <section className="hot-section">
      {/* Header */}
      <div className="hot-header">
        <div className="hot-header__left">
          <h2 className="hot-title">Scelti Per Te</h2>
          {/*<img
            className="hot-title__emoji"
            src="/icons8-fire-100.png"
            alt="fire icon"
          />*/}
        </div>
        <button
          className="hot-link"
          onClick={() => navigateTo(navigate, "/Shop")}
        >
          Visita Store
        </button>
      </div>

      {/* Responsive product grid */}
      <div className="hot-catalog-grid">{renderHotProducts()}</div>
    </section>
  );
};

export default CatalogHome;